sql.if:
AND EXISTS (
    SELECT 1
    FROM yak_ops_sql_statement_execution sf
    WHERE sf.execution_id = e.execution_id

        AND sf.statement_type = #{query.statementType}


        AND sf.sql_fingerprint = #{query.sqlFingerprint}

)

mapper.select:
SELECT ranked.duration_ms FROM ( SELECT e.duration_ms, ROW_NUMBER() OVER (ORDER BY e.duration_ms) AS row_number_value, COUNT(*) OVER () AS total_count FROM yak_ops_sql_execution e
1 = 1
) ranked WHERE ranked.row_number_value >= CEIL(ranked.total_count * 0.95) ORDER BY ranked.row_number_value LIMIT 1

SELECT s.statement_type AS statement_type, COUNT(*) AS count FROM yak_ops_sql_statement_execution s INNER JOIN yak_ops_sql_execution e ON e.execution_id = s.execution_id
1 = 1
AND s.statement_type = #{query.statementType}
AND s.sql_fingerprint = #{query.sqlFingerprint}
GROUP BY s.statement_type ORDER BY count DESC, s.statement_type ASC
